# Correct the copied final row to the stated 22-column input, then fill enclosed rectangular outlines.
if len(g[-1]) == 21: g[-1].append(6)
from collections import deque
h,w=len(g),len(g[0]); seen=set(); out=[row[:] for row in g]
for r in range(h):
 for c in range(w):
  color=g[r][c]
  if color==6 or (r,c) in seen: continue
  q=[(r,c)]; seen.add((r,c)); comp=[]
  while q:
   y,x=q.pop(); comp.append((y,x))
   for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
    yy,xx=y+dy,x+dx
    if 0<=yy<h and 0<=xx<w and (yy,xx) not in seen and g[yy][xx]==color:
     seen.add((yy,xx)); q.append((yy,xx))
  r0=min(y for y,x in comp); r1=max(y for y,x in comp); c0=min(x for y,x in comp); c1=max(x for y,x in comp)
  # closed rectangular border; fill its empty interior
  if all(g[y][x]==color for y,x in comp) and all(g[y][x]==color for y,x in [(r0,x) for x in range(c0,c1+1)]+[(r1,x) for x in range(c0,c1+1)]+[(y,c0) for y in range(r0,r1+1)]+[(y,c1) for y in range(r0,r1+1)]):
   fill=2 if (r1-r0+1)==(c1-c0+1) and (r1-r0+1)%2==0 else 7
   for y in range(r0+1,r1):
    for x in range(c0+1,c1):
     if g[y][x]==6: out[y][x]=fill
print(h,w,set(map(len,out)))
print('\n'.join(' '.join(map(str,row)) for row in out))
